"""Chapter 5: conclusions, discussion and recommendations."""
from ch4_common import *


def ph(x):
    return f"<ph>{x}</ph>"


def build(b, N):
    res = N["lca"]
    b.h1(5, "สรุปผลการวิจัย อภิปรายผล และข้อเสนอแนะ")
    b.p(ot(365, {"ถ่านชีวภาพจากไม้ไผ่เป็นวัสดุทดแทนบางส่วนในการผลิตคอนกรีตบล็อกปูพื้น": "ถ่านชีวภาพจากไม้ไผ่เป็นวัสดุทดแทนซีเมนต์บางส่วนในการผลิตคอนกรีตบล็อกปูพื้น"}))
    b.h2("5.1 สรุปผลการวิจัยและอภิปรายผล")
    b.fig("rsummary", fp("s_summary"), 15.0, "สรุปผลสำคัญของงานวิจัย การทดสอบกำลังอัด ความหนาแน่น และการดูดซึมน้ำเป็นค่าที่วัด ส่วนค่าความต้านทานการลื่นไถลเป็นค่าสมมติ " + PH + " และ GWP เป็นค่าคำนวณเบื้องต้น")
    items = [
        f"<b>1. ความหนาแน่น</b> ความหนาแน่นของบล็อกชุดที่ 1 ลดลงเมื่อใช้ถ่านชีวภาพทดแทนซีเมนต์มากขึ้น ค่าเฉลี่ยรวมของสูตร NA RA Rab5% Rab10% และ Rab15% เท่ากับ {d0(N['rho_all_NA'])} {d0(N['rho_all_RA'])} {d0(N['rho_all_Rab5'])} {d0(N['rho_all_Rab10'])} และ {d0(N['rho_all_Rab15'])} กก./ม.³ ตามลำดับ (ลดราว {abs(dens_fit()[0]):.0f} กก./ม.³ ต่อการลดซีเมนต์ร้อยละ 1) สอดคล้องกับโครงสร้างพรุนของถ่านชีวภาพ ค่าทั้งหมดอยู่ในช่วงคอนกรีตน้ำหนักปกติ",
        f"<b>2. กำลังอัด ชุดที่ 1</b> ที่ 28 วัน สูตร RA Rab5% Rab10% และ Rab15% มีกำลังอัดเฉลี่ย {f2(N['fc28_RA'])} {f2(N['fc28_Rab5'])} {f2(N['fc28_Rab10'])} และ {f2(N['fc28_Rab15'])} MPa ทุกสูตรผ่านเกณฑ์ มอก. 827-2565 (35 MPa) สูตรที่ผ่านเกณฑ์ มอก. 2035-2565 (50 MPa) คือ NA RA และ Rab5% ซึ่งแก้ไขจากร่างเดิมที่ระบุเฉพาะ RA การลดซีเมนต์ร้อยละ 5 ทำให้กำลังลดลงร้อยละ {abs(pct(N['fc28_Rab5'], N['fc28_RA'])):.0f} และร้อยละ 10–15 ทำให้ลดลงร้อยละ {abs(pct(N['fc28_Rab10'], N['fc28_RA'])):.0f}–{abs(pct(N['fc28_Rab15'], N['fc28_RA'])):.0f} ส่วนใหญ่อธิบายได้ด้วยซีเมนต์ที่ลดลงและความหนาแน่นที่ลดลง จึงควรจำกัดการลดซีเมนต์ไว้ไม่เกินร้อยละ 5 หากต้องการรักษาระดับกำลังใกล้เกณฑ์งานหนัก",
        f"<b>3. กำลังอัด ชุดที่ 2</b> ภายใต้ถ่านชีวภาพคงที่ การแทนที่ทรายด้วย RCA ร้อยละ 0 5 10 และ 15 ให้กำลังอัดที่ 28 วันเท่ากับ {f2(N['fc28_RCA0'])} {f2(N['fc28_RCA5'])} {f2(N['fc28_RCA10'])} และ {f2(N['fc28_RCA15'])} MPa ตามลำดับ (เพิ่มร้อยละ {pct(N['fc28_RCA15'], N['fc28_RCA0']):.0f} ที่ RCA 15%) ทุกสูตรผ่านเกณฑ์ทั้งสอง สูตรที่ดีที่สุดในการทดลองนี้คือ RCA ร้อยละ 15 ร่วมกับถ่านชีวภาพ 48 กรัม แต่ผลนี้ขัดกับงานส่วนใหญ่ที่รายงานว่า RCA ลดกำลัง กลไกที่ร่างเดิมเสนอยังไม่ได้ยืนยัน และต้องตรวจขนาดคละและการดูดน้ำของ RCA",
        f"<b>4. กลศาสตร์ของกำลังอัด</b> กำลังอัดของชุดที่ 1 แปรตามความหนาแน่นยกกำลังประมาณ {N['b_rho_28']:.0f} (R² = {N['r2_rho_28']:.2f} ที่ 28 วัน) และของสูตร RA ถึง Rab15% แปรตามปริมาณซีเมนต์ด้วยความชัน {N['b_cem']:.2f} MPa ต่อ กก./ม.³ ตำแหน่งของ RA ที่ต่ำกว่าเส้นความสัมพันธ์ความหนาแน่น–กำลังแสดงว่า RCA ลดกำลังด้วยกลไกที่ไม่ใช่ความพรุนรวม เช่น บริเวณรอยต่อ ITZ ผลนี้อาศัยข้อมูลเพียง 5 จุดและเป็นการตีความ",
        "<b>5. การพัฒนากำลังตามอายุ</b> สูตร NA Rab5% Rab10% และ Rab15% พัฒนากำลังตามที่แบบจำลองความแก่ของ EN 1992-1-1 คาดไว้ แต่สูตร RA และทุกสูตรของชุดที่ 2 มีกำลังต้นอายุต่ำผิดปกติเมื่อเทียบกับ 28 วัน ซึ่งอาจมาจากการบ่ม ชนิดซีเมนต์ หรือการที่ก้อนต่างอายุเป็นคนละชุดผสม ต้องตรวจสอบก่อนอ้างกำลังต้นอายุ",
        f"<b>6. การดูดซึมน้ำ</b> ค่าการดูดซึมน้ำที่ 72 ชั่วโมงของทุกสูตรต่ำกว่าเกณฑ์ร้อยละ 5 ของ มอก. 2035-2565 และ ASTM C936 และร้อยละ 6 ของ EN 1338 สูตร Rab5% เฉลี่ยร้อยละ {N['ab_rab5_all']:.2f} แต่มี 3 รายการของชุดที่ 2 ที่ผิดปกติหรือซ้ำและรอการทดสอบซ้ำ ความละเอียดของเครื่องชั่งทำให้เปรียบเทียบความแตกต่างต่ำกว่าร้อยละ 0.3 ไม่ได้",
        f"<b>7. ความต้านทานการลื่นไถล</b> {PH} ยังไม่มีผลวัดจริง ผู้วิจัยจัดทำกรอบวิเคราะห์ ตารางผลสมมติ และเกณฑ์ตัดสิน (45 และ 60 BPN ซึ่งยังต้องยืนยัน) ให้แทนที่ด้วยข้อมูลจริงได้ทันที ผลสมมติไม่ใช่ข้อสรุปของงานวิจัย",
        f"<b>8. ผลิตภัณฑ์ท้องตลาดและรูปทรงชิ้นทดสอบ</b> บล็อกงานวิจัยมีกำลังอัด {f2(N['mk_this'])} MPa เทียบกับ {f2(N['mk_A'])} และ {f2(N['mk_B'])} MPa ของผลิตภัณฑ์สองร้านที่ทดสอบ (ทุกก้อนต่ำกว่า 35 MPa) ผลนี้ไม่ใช่ข้อสรุปเชิงสถิติของตลาด บล็อกรูปคดกริชให้กำลังสูงกว่าชิ้นทรงลูกบาศก์ {N['shape10']:.2f}–{N['shape0']:.2f} เท่า จึงไม่ควรเทียบกำลังอัดของบล็อกกับค่าของคอนกรีตโครงสร้างโดยตรง",
        f"<b>9. คาร์บอนและต้นทุน</b> ซีเมนต์คิดเป็นร้อยละ {N['share_min']:.0f}–{N['share_max']:.0f} ของ GWP การลดซีเมนต์ร้อยละ 5–15 ลด GWP กรณี A ลงร้อยละ {abs(res.loc['Rab5','gwp_A_vs_ctrl_pct']):.1f}–{abs(res.loc['Rab15','gwp_A_vs_ctrl_pct']):.1f} แต่ ci แย่ลงจาก {N['ciA_RA']:.2f} เป็น {N['ciA_Rab15']:.2f} kg CO<sub>2</sub>e ต่อ ม.³ ต่อ MPa กรณี B (นับเครดิตคาร์บอนที่คงอยู่ในไบโอชาร์ตามสมมติฐาน) ลด GWP ได้ร้อยละ {abs(pct(N['gwpB_Rab5'], N['gwpB_RA'])):.0f}–{abs(pct(N['gwpB_Rab15'], N['gwpB_RA'])):.0f} ต้นทุนวัสดุเท่ากับ RA เมื่อไบโอชาร์มีราคาราวสองในสามของซีเมนต์ และต้นทุนต่อ MPa ไม่ดีขึ้นแม้ไบโอชาร์ฟรี ตัวประกอบการปล่อยหลายตัวเป็นค่าสมมติ {PH}",
        "<b>10. ภาพรวม</b> ผลที่วัดได้แสดงว่าเศษคอนกรีตเหลือทิ้งในระดับร้อยละ 15 ของทรายและถ่านชีวภาพที่ทดแทนซีเมนต์ไม่เกินร้อยละ 15 ใช้ผลิตบล็อกปูพื้นที่ผ่านเกณฑ์กำลังอัดทั่วไปของ มอก. 827-2565 ได้ในระดับห้องปฏิบัติการ โดยประโยชน์ด้านการลดซีเมนต์เป็นรูปธรรมที่สุดในกรณีที่เลือกระดับ Rab5% สำหรับงานหนัก ผลนี้สนับสนุนเป้าหมายการพัฒนาที่ยั่งยืนข้อ 9 12 และ 13 {c:un2015} ในระดับของข้อมูลเบื้องต้น ไม่ใช่การยืนยันผลกระทบเชิงระบบ (ดู{fig:rsdg})",
    ]
    for it in items:
        b.plain(it, left=567, hanging=567, after=100, first=False)
    b.fig("rsdg", fp("s_sdg_impact"), 15.0, "ประโยชน์เชิงปริมาณเบื้องต้นที่เชื่อมกับเป้าหมายการพัฒนาที่ยั่งยืนข้อ 9 12 และ 13 ตัวเลขมาจากการคำนวณเบื้องต้นของงานนี้และต้องยืนยันก่อนใช้อ้างอิงภายนอก")
    b.h2("5.2 อภิปรายผลเชิงบูรณาการ")
    b.p("ผลของงานนี้เสนอข้อสังเกตสามข้อที่ต่างจากข้อสรุปของร่างเดิมหรือที่ร่างเดิมยังไม่ได้พิจารณา ข้อแรก ถ่านชีวภาพที่ใช้ทดแทนซีเมนต์ในบล็อกอัดแน่นไม่ได้ให้ประโยชน์ด้านกำลังแบบที่รายงานในมอร์ตาร์ปริมาณน้อยของงานบางชิ้น ({c:suarez2020,sacdalan2023,legan2025}) แต่ให้ผลที่สอดคล้องกับงานที่พบว่าปริมาณสูงลดกำลัง ({c:wang2020,abbas2025}) ข้อที่สอง ประโยชน์ด้านคาร์บอนของการทดแทนซีเมนต์ด้วยไบโอชาร์ขึ้นกับว่านับเครดิตการกักเก็บคาร์บอนหรือไม่อย่างมาก การลดซีเมนต์เพียงอย่างเดียวช่วยน้อยเพราะกำลังเสียเร็วกว่า GWP ที่ลด ข้อที่สาม ประโยชน์ของ RCA ในงานนี้เป็นเรื่องการใช้วัสดุเหลือทิ้งและกำลังอัดที่ยังผ่านเกณฑ์ ไม่ใช่ GWP เพราะแบบจำลองไม่นับการหลีกเลี่ยงการฝังกลบ (กฎ cut-off) ({c:knoeri2013,pizon2026})")
    b.p("เมื่อเทียบกับกรอบสมมติฐานในหัวข้อ 1.5 สมมติฐาน H1 H2 H4 ได้รับการสนับสนุนจากข้อมูล H5 ไม่ได้รับการสนับสนุนในกรณี A และ H3 ยังทดสอบไม่ได้ ({tab:rhyp}) สิ่งที่งานนี้เพิ่มเติมจากงานวิจัยก่อนหน้าคือ ข้อมูลบล็อกอัดแน่นที่ใช้ทั้ง RCA และไบโอชาร์จากไผ่พร้อมกัน การแยกบทบาทของซีเมนต์ที่ลดลงกับอนุภาคไบโอชาร์ต่อกำลังอัด และกรอบประเมินคาร์บอนที่แยกกรณีไม่นับและนับเครดิต ข้อมูลทั้งหมดยังมีข้อจำกัดด้านจำนวนตัวอย่างตามที่ระบุในหัวข้อ 4.10 จึงควรถือเป็นผลเบื้องต้นที่ต้องยืนยันด้วยตัวอย่างที่มากขึ้นและวัสดุตั้งต้นที่ทราบสมบัติ")
    b.h2("5.3 ข้อเสนอแนะ")
    recs = [
        "1. ทดสอบให้ครบตามขอบเขตที่ออกแบบ ทั้งการลดซีเมนต์ร้อยละ 20 และ 25 การทดสอบความต้านทานการลื่นไถลสภาวะแห้งและเปียกทุกสูตร และยืนยันเกณฑ์ BPN จากต้นฉบับมาตรฐาน เพื่อแทนที่ค่าสมมติในหัวข้อ 4.5",
        "2. ทดสอบซ้ำการดูดซึมน้ำของ RCA 10% และ RCA 15% ที่ 14 วัน และ RCA 15% ที่ 28 วัน และหล่อก้อนทุกอายุจากชุดผสมเดียวกัน บันทึกอุณหภูมิบ่ม และเก็บค่าดิบรายก้อนโดยไม่ปัดเศษ",
        "3. วัดสมบัติของวัสดุตั้งต้น ได้แก่ ไบโอชาร์ (ขนาดอนุภาค ความหนาแน่น การดูดซับน้ำ pH ปริมาณคาร์บอน) และ RCA (ขนาดคละ การดูดซึมน้ำ ปริมาณมอร์ตาร์เดิม) พร้อมปริมาณน้ำที่ใช้ในแต่ละสูตร เพื่ออธิบายกลไกของผลที่ขัดกับงานอื่น",
        "4. ศึกษาโครงสร้างจุลภาคด้วย SEM และวัดความพรุนเปิดหรือการดูดซึมแบบสุญญากาศ เพื่อยืนยันบทบาทของไบโอชาร์และ ITZ ของ RCA ต่อกำลังอัด ตามที่เสนอในหัวข้อ 4.3.4",
        "5. ทดสอบทางเลือกที่งานอื่นรายงานว่าช่วยกำลัง ได้แก่ การบดไบโอชาร์ให้ละเอียด การเติมในปริมาณต่ำกว่าร้อยละ 5 การกระตุ้นสารเคมี และการบ่มด้วย CO<sub>2</sub> ({c:sacdalan2023,chin2025,hylton2024})",
        "6. ขยายการศึกษาสู่ความคงทน เช่น การเปียกสลับแห้ง การซึมผ่านของน้ำ ความต้านทานการสึกกร่อนของผิวหน้า และพฤติกรรมในสภาพแวดล้อมจริงในระยะยาว",
        "7. ยกระดับการประเมินวัฏจักรชีวิตจากแบบเบื้องต้นเป็นฉบับสมบูรณ์ตาม ISO 14040/14044 {c:iso14040,iso14044} โดยใช้ข้อมูลบัญชีรายการของประเทศไทย ขอบเขตรวมการขนส่งและการใช้งาน ตรวจสอบสัดส่วนคาร์บอนและความคงอยู่ของไบโอชาร์ และทำการวิเคราะห์ต้นทุนและผลตอบแทนด้วยราคาจริง",
        "8. ทดสอบการใช้งานจริงในภาคสนาม เช่น ทางเดินเท้าหรือลานอเนกประสงค์ เพื่อประเมินสมรรถนะและความทนทาน และเป็นแนวทางถ่ายทอดเทคโนโลยีสู่วิสาหกิจชุมชน",
        "9. จัดทำระบบบันทึกข้อมูลผลทดสอบแบบเดียวกัน (ไฟล์ข้อมูลดิบพร้อมรหัสก้อนทดสอบ) เพื่อป้องกันความคลาดเคลื่อนระหว่างตารางกับข้อความบรรยายตามข้อสังเกตในภาคผนวก ข",
    ]
    for r_ in recs:
        b.plain(r_, left=567, hanging=567, after=80, first=False)
